/** Native workbench recovery controls; upstream outcomes are controlled by incremental-references-ui.mjs. */
async page => {
  const assert = (condition, message) => { if (!condition) throw new Error(message) }
  const pageErrors = [], onError = error => pageErrors.push(error.message)
  page.on('pageerror', onError)
  const dialog = page.getByRole('dialog', { name: '图库引入已中断', exact: true })
  try {
    await page.setViewportSize({ width: 1440, height: 900 })
    await page.evaluate(() => window.incrementalFixture.showGalleryRecovery())
    await dialog.waitFor()
    assert((await dialog.innerText()).includes('170 / 299'), 'The dialog must retain saved progress')
    assert((await dialog.innerText()).includes('剩余 129'), 'Unconfirmed and failed photos remain eligible for reconciliation')
    assert(await page.locator('.vc-profile-actions .vc-gallery-task-status').count() === 0, 'The sidebar must not repeat the recovery notice')
    await page.waitForFunction(() => { const image = document.querySelector('.vc-gallery-recovery-art'); return image?.complete && image.naturalWidth === 480 })
    assert(await dialog.getByRole('progressbar').getAttribute('aria-valuenow') === '170', 'Progress must show saved images rather than failed attempts')
    const frosted = element => { const material = getComputedStyle(element, '::before'); return getComputedStyle(element).backgroundColor === 'rgba(0, 0, 0, 0)' && material.backdropFilter.includes('blur(') && material.backgroundColor.startsWith('rgba(') }
    assert(await dialog.evaluate(frosted), 'The dialog must use a translucent surface and blur the page behind it')
    const glyphs = await dialog.locator('svg[data-icon]').evaluateAll(icons => icons.filter(icon => { const use=icon.querySelector('use');if(!use)return false;const box=use.getBBox();return box.width>0&&box.height>0 }).map(icon=>icon.getAttribute('data-icon')))
    assert(glyphs.includes('dsw-icon-archive-check-outline-regular') && glyphs.includes('dsw-icon-play-outline-medium') && glyphs.includes('dsw-icon-close-outline-regular'), 'Saved, continue and close controls must render their native glyphs')
    await dialog.screenshot({ path: '.playwright-mcp/gallery-recovery-redesigned-dark.png', animations: 'disabled' })
    await dialog.getByRole('button', { name: '关闭', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' })
    assert(await page.evaluate(() => (window.incrementalFixture.state.galleryControls?.length ?? 0) === 0 && window.incrementalFixture.galleryTasks()[0].status === 'needs-review'), 'Closing must only dismiss the dialog without sending cancellation')
    const card = page.locator('.vc-gallery-recovery-entry-card')
    assert(await card.evaluate(element=>element.getBoundingClientRect().width<=440&&parseFloat(getComputedStyle(element).borderTopWidth)>0), 'The retained task must use a compact outlined tag card')
    await page.locator('.vc-gallery-recovery-entry-card').waitFor()
      if (!(await dialog.isVisible())) await page.locator('.vc-gallery-recovery-entry').getByRole('button', { name: '继续引入', exact: true }).click()
    await dialog.waitFor()
    await page.evaluate(() => { window.incrementalFixture.state.holdGalleryControl = true })
    await dialog.getByRole('button', { name: '继续引入', exact: true }).click()
    await page.waitForFunction(() => window.incrementalFixture.state.galleryControls?.length === 1)
    assert(await dialog.locator('.vc-task-footer button:disabled').count() === 2, 'Both actions must be disabled while acknowledgement is pending')
    await dialog.getByRole('button', { name: '关闭', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' })
    await page.evaluate(() => window.incrementalFixture.releaseGalleryControl())
    await page.waitForFunction(() => window.incrementalFixture.galleryTasks()[0].status === 'running')
    assert(await page.evaluate(() => window.incrementalFixture.galleryTasks()[0].completed) === 170, 'Continue must keep successful images')
    await page.evaluate(() => { window.incrementalFixture.state.galleryControlFailure = true; window.incrementalFixture.showGalleryRecovery() })
    await page.locator('.vc-gallery-recovery-entry-card').waitFor()
      if (!(await dialog.isVisible())) await page.locator('.vc-gallery-recovery-entry').getByRole('button', { name: '继续引入', exact: true }).click()
    await dialog.getByRole('button', { name: '继续引入', exact: true }).click()
    await dialog.getByRole('alert').waitFor()
    assert(await dialog.isVisible(), 'An unknown acknowledgement must keep recovery available')
    assert((await dialog.getByRole('alert').innerText()).includes('继续引入未完成') && (await dialog.getByRole('alert').innerText()).includes('请求结果尚未确认'), 'An unknown outcome must identify the failed command without claiming cancellation or success')
    assert(!(await dialog.innerText()).includes('fixture-connection-unavailable'), 'Private exception text must not become product copy')
    for (const [code, message] of [['constraint-conflict', '检查素材集状态和其他引入任务'], ['capability-unavailable', '重新加载插件后重试']]) {
      await page.evaluate(code => { window.incrementalFixture.state.galleryControlFailure = code }, code)
      await dialog.getByRole('button', { name: '继续引入', exact: true }).click()
      await page.waitForFunction(code => document.querySelector('.vc-gallery-recovery-error-code')?.textContent?.includes(code), code)
      assert((await dialog.getByRole('alert').innerText()).includes(message), 'A declared failure must show its reason and safe next action')
    }
    await page.evaluate(() => { window.incrementalFixture.state.galleryControlFailure = { code: 'owner-denied', stage: 'data-read' } })
    await dialog.getByRole('button', { name: '继续引入', exact: true }).click()
    await page.waitForFunction(() => document.querySelector('[role="alert"]')?.textContent?.includes('重启应用后重试'))
    assert(!(await dialog.getByRole('alert').innerText()).includes('账号'), 'A stale Host route must request an application restart rather than a gallery account change')
    await page.evaluate(() => { window.incrementalFixture.state.galleryControlFailure = 'source-request-timeout' })
    await dialog.getByRole('button', { name: '取消引入', exact: true }).click()
    await page.waitForFunction(() => document.querySelector('[role="alert"]')?.textContent?.includes('取消结果尚未确认'))
    assert((await dialog.getByRole('alert').innerText()).includes('请求超时') && await page.evaluate(() => window.incrementalFixture.galleryTasks()[0].status === 'needs-review'), 'A failed cancellation must retain the task and report the cancellation outcome as unconfirmed')
    await dialog.screenshot({ path: '.playwright-mcp/gallery-recovery-frosted-error.png', animations: 'disabled' })
    await page.evaluate(() => { window.incrementalFixture.state.galleryControlFailure = false })
    await dialog.locator('.vc-task-footer').getByRole('button', { name: '取消引入', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' })
    assert(await page.evaluate(() => window.incrementalFixture.galleryTasks()[0].status === 'cancelled'), 'Cancel import must end the original task')
    for (const dark of [true, false]) {
      await page.setViewportSize({ width: 390, height: 844 })
      await page.evaluate(dark => { window.incrementalFixture.theme(dark); window.incrementalFixture.showGalleryRecovery() }, dark)
      await page.locator('.vc-gallery-recovery-entry-card').waitFor()
      if (!(await dialog.isVisible())) await page.locator('.vc-gallery-recovery-entry').getByRole('button', { name: '继续引入', exact: true }).click()
      await dialog.waitFor()
      assert(await dialog.evaluate(frosted), 'Both light and dark themes must keep the frosted material')
      const fits = await dialog.evaluate(element => { const box = element.getBoundingClientRect(); return box.left >= 0 && box.right <= innerWidth && box.top >= 0 && box.bottom <= innerHeight && element.scrollWidth <= element.clientWidth + 1 })
      assert(fits, 'The recovery dialog must fit narrow light and dark viewports')
      if (!dark) await dialog.screenshot({ path: '.playwright-mcp/gallery-recovery-redesigned-light-narrow.png', animations: 'disabled' })
      await page.keyboard.press('Escape')
      await dialog.waitFor({ state: 'hidden' })
      assert(await page.evaluate(() => window.incrementalFixture.galleryTasks()[0].status === 'needs-review'), 'Escape must retain the unfinished task')
    }
    const controls = await page.evaluate(() => window.incrementalFixture.state.galleryControls)
    assert(pageErrors.length === 0, 'Recovery must not produce uncaught browser errors')
    return { saved: 170, total: 299, remaining: 129, sidebarNotices: 0, resumeRequests: controls.filter(item => item.command === 'resume').length, cancelRequests: controls.filter(item => item.command === 'cancel').length, closeDismissesWithoutCancellation: true, closeWhilePending: true, reopenFromPage: true, cancelEndsTask: true, artworkLoaded: true, frostedMaterial: true, nativeIconsVisible: true, taskEntry: 'tag-card', pendingActionsDisabled: true, failedActionRetainedDialog: true, failureReasonsVisible: true, hostRestartHint: true, failedCancellationRetainsTask: true, narrowOverflow: false, themes: ['dark', 'light'], pageErrors }
  } finally { page.off('pageerror', onError) }
}
